// The Python model, for every R0 from 0.5 to 6.
const N = 1e6, DT = 0.25, MAX_DAYS = 5000;
const days = nb.get('sir_days') ?? 7;
const gamma = 1 / days;
const current = nb.get('sir_r0') ?? 2.5;

function run(r0) {
  const beta = r0 * gamma;
  const deriv = ([S, I]) => {
    const inf = beta * S * I / N;
    return [-inf, inf - gamma * I, gamma * I];
  };
  const add = (a, b, h) => a.map((v, i) => v + h * b[i]);
  let s = [N - 10, 10, 0];
  let peak = s[1];
  for (let t = 0; s[1] >= 1 && t < MAX_DAYS; t += DT) {   // until under one person is infected
    const k1 = deriv(s), k2 = deriv(add(s, k1, DT / 2)), k3 = deriv(add(s, k2, DT / 2)), k4 = deriv(add(s, k3, DT));
    s = s.map((v, i) => v + DT / 6 * (k1[i] + 2 * k2[i] + 2 * k3[i] + k4[i]));
    peak = Math.max(peak, s[1]);
  }
  return { peak: peak / N, total: s[2] / N, herd: Math.max(0, 1 - 1 / r0) };
}

const rows = [];
const byR0 = {};
for (let i = 5; i <= 60; i++) {
  const r0 = i / 10;
  const r = run(r0);
  byR0[r0] = r;
  rows.push({ r0, share: r.peak, measure: 'peak (ill at once)' });
  rows.push({ r0, share: r.total, measure: 'final size (ever infected)' });
  rows.push({ r0, share: r.herd, measure: 'herd threshold 1 - 1/R0' });
}

const pct = x => (100 * x).toFixed(1) + '%';
console.log('days infectious:', days);
for (const r0 of [1.5, 3]) {
  const r = byR0[r0];
  console.log('R0 ' + r0 + ': peak ' + pct(r.peak) + ', final size ' + pct(r.total) + ', herd threshold ' + pct(r.herd));
}
const hi = byR0[3], lo = byR0[1.5];
console.log('halving R0 from 3 to 1.5 cuts the peak by ' + pct(1 - lo.peak / hi.peak) +
  ' and the total by ' + pct(1 - lo.total / hi.total));

const py = nb.get('sir_run');
if (py && py.days === days) {
  const mine = run(py.r0);
  const gap = Math.max(Math.abs(mine.peak - py.peak), Math.abs(mine.total - py.finalSize));
  console.log('check against the Python run at R0 ' + py.r0 + ': largest difference ' +
    (100 * gap).toFixed(4) + ' percentage points');
}

return {
  $schema: 'https://vega.github.io/schema/vega-lite/v5.json',
  width: 'container',
  height: 300,
  title: 'What R0 decides (' + days + ' days infectious)',
  encoding: { x: { field: 'r0', type: 'quantitative', title: 'R0' } },
  layer: [
    {
      data: { values: rows },
      mark: { type: 'line', strokeWidth: 2 },
      encoding: {
        y: { field: 'share', type: 'quantitative', title: 'share of population', axis: { format: '%' } },
        color: { field: 'measure', type: 'nominal', title: null },
        strokeDash: { condition: { test: "datum.measure === 'herd threshold 1 - 1/R0'", value: [5, 4] }, value: [1, 0] },
      },
    },
    {
      data: { values: [{ r0: current }] },
      mark: { type: 'rule', color: '#94a3b8' },
    },
  ],
};
